/**
 * File-size rule (AGENTS.md "File size", issue #76): hand-written code and CSS aims for ≤ 300 lines, gets a review
 * above 500 and never goes above 800.
 *
 *   npx tsx scripts/site/file-size.ts           → warn above 500, exit 1 above 800 (or on a stale allowlist entry)
 *   npx tsx scripts/site/file-size.ts --quiet   → only print failures
 *
 * Covers `src/**` and `scripts/**`, files ending `.ts`, `.tsx` or `.css`. Generated data is exempt: any file whose
 * header (first 400 characters) says "Generated by". JSON (goldens, ids.json) is out of scope by extension.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'

const ROOTS = ['src', 'scripts']
const EXT = /\.(ts|tsx|css)$/
const WARN = 500
const FAIL = 800

/** Files still over 800 lines, each waiting on its split. Remove the entry when the file comes under the limit. */
const ALLOW: Record<string, string> = {
  'scripts/editor-browser.ts': '#76: split per phase (editor is backlog)',
}

const quiet = process.argv.includes('--quiet')

function walk(dir: string, out: string[]): void {
  for (const name of readdirSync(dir)) {
    if (name === 'node_modules' || name.startsWith('.')) continue
    const p = join(dir, name)
    if (statSync(p).isDirectory()) walk(p, out)
    else if (EXT.test(name)) out.push(p)
  }
}

const files: string[] = []
for (const r of ROOTS) walk(r, files)

const warns: string[] = []
const fails: string[] = []
const allowed: string[] = []
const seen = new Set<string>()
for (const f of files.sort()) {
  const rel = relative('.', f).replace(/\\/g, '/')
  const text = readFileSync(f, 'utf8')
  if (/Generated by/.test(text.slice(0, 400))) continue
  const lines = text.split('\n').length - (text.endsWith('\n') ? 1 : 0)
  if (rel in ALLOW) {
    seen.add(rel)
    if (lines > FAIL) allowed.push(`${String(lines).padStart(5)}  ${rel}  (allowlisted, ${ALLOW[rel]})`)
    else fails.push(`${String(lines).padStart(5)}  ${rel}  is under ${FAIL} now: remove its allowlist entry`)
  } else if (lines > FAIL) fails.push(`${String(lines).padStart(5)}  ${rel}  is over ${FAIL} lines: split it by concern`)
  else if (lines > WARN) warns.push(`${String(lines).padStart(5)}  ${rel}`)
}
for (const rel of Object.keys(ALLOW)) if (!seen.has(rel)) fails.push(`      ${rel}  is allowlisted but missing: remove the entry`)

if (!quiet) {
  if (warns.length) console.log(`file-size: ${warns.length} file(s) over ${WARN} lines (review when next touched)\n${warns.join('\n')}`)
  if (allowed.length) console.log(`file-size: ${allowed.length} allowlisted file(s) over ${FAIL}\n${allowed.join('\n')}`)
}
if (fails.length) {
  console.error(`file-size: FAIL\n${fails.join('\n')}`)
  process.exit(1)
}
console.log(`file-size: ok (${files.length} files, ${warns.length} over ${WARN}, ${allowed.length} allowlisted)`)
